function useCart() {                       // extractable state logic
  const snapshot = useSyncExternalStore(store.subscribe, store.getSnapshot);
  return { lines: snapshot.lines, add: (sku) => store.add(sku) };
}
export function CartPage() {               // container
  const { lines, add } = useCart();
  return <CartLines lines={lines} onAdd={add} />;
}
function CartLines({ lines, onAdd }) {     // stateless child
  return <ul>{lines.map((l) => <li key={l.sku}>{l.qty}</li>)}</ul>;
}

