class CartPage extends React.Component {
  state = { lines: [] };                       // container state
  componentDidMount() {
    this.unsub = store.subscribe(() => this.setState({ lines: store.lines }));
  }
  componentWillUnmount() { this.unsub(); }
  render() {                                    // pure: props/state only
    return <CartLines lines={this.state.lines} />;
  }
}
